old=(O/'transient-stage-filter.html').read_text();css=old[old.index('<style>'):old.index('</style>')+8];oldjs=old[old.index('function sync()'):old.index('function render()')];oldjs=oldjs[:oldjs.index('function buttons')]+oldjs[oldjs.index('function buttons'):]
html='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>원본 직접 크기·위상 보정 비교</title>'''+css+'''<main><nav><a href="transient-stage-filter.html">이전 어택·본체 처리</a><a href="reference-magnitude-diagnostic.html">참조 시간별 처리</a><a href="index.html">분석 홈</a><a href="complex-linear-percussion.json">설계·정렬·계수·전체 평가</a></nav><h1>원본에서 직접 추정한 크기 보정과 위상 보정</h1><p>기존 EQ에 더 쌓지 않고 원본에서 직접 4,097탭 FIR을 추정했습니다. 정규화 교차응답으로 만든 FIR의 실제 크기에 맞춘 <b>크기전용 대조 후보</b>와 <b>위상도 반영한 후보</b>입니다. 첫 8타격으로 채널·시간 이동·기준 게인·계수를 고정하고 마지막 5타격에 그대로 적용했습니다.</p><p class="notice"><b>같은 세션의 개발 비교입니다.</b> 마지막 5타격도 앞선 실험에서 들어본 자료입니다. 평가 타격별 시간·게인을 다시 맞추지 않았습니다. 이번 400ms 관측창은 이전 duration 점수와 다르므로 앞선 점수와 절댓값을 직접 비교하지 마세요. 위상 보정은 파형 관계가 일관된 대역에서만 반영합니다. 기존 스피커 IR의 역필터나 실시간 구현 완료 결과가 아닙니다.</p><p><b>결과:</b> 크기+위상은 크기전용보다 파형 오차를 iPhone 약0.50dB, S21 약0.18dB 줄였지만, 시간·대역 크기 오차는 거의 같습니다. 두 실제 FIR 크기 응답에도 작은 차이가 남아 순수 위상 효과를 완전히 분리했다고 보지는 않습니다. 특히 iPhone은 타격마다 최대상관 시차가 달라 고정 응답의 안정성이 제한됩니다. S21은 이전 퍼커션 FIR이 대역 점수에서 더 좋았습니다. 새 권장 필터로 교체하지 않고 비교 후보로 보존합니다.</p><div class="layout"><aside><h3>주법</h3><div id="groups"></div><h3>기기</h3><div id="devices"></div></aside><section class="panel"><h2 id="selection"></h2><div id="variants" class="controls"></div><p id="description"></p><div class="controls"><button id="rawtoggle">가운데: 원본 보기</button><button id="stop">일시정지</button><button id="rewind">처음으로</button><input id="seek" type="range" min="0" max="5" step="0.005" value="0" aria-label="공통 재생 위치"><span id="clock">0 / 5초</span></div><div class="cards" id="cards"></div><p class="small">이미지를 누르면 해당 소리의 클릭한 시각부터 즉시 재생합니다. 버튼 전환도 같은 시각에서 이어집니다. 새 두 후보는 같은 train 게인을 사용합니다. 기존 완성 필터는 같은200–600Hz 기준으로 train 출력게인을 고정하며, 안전 배율은 공통입니다. 잔차는 기기−KM184, 빨강 과다 / 파랑 부족(±12dB)입니다.</p><h3>현재 클립의 오차</h3><div class="wide" id="metrics"></div><p class="small">시간·대역 MAE는 원본 양쪽 신호가 관측되는600Hz–12kHz에서 동일 confidence로 계산합니다. 20ms/85ms SC는 해당 창의 전대역 크기 스펙트럼 차이 비율입니다(0이면 동일). 파형 NMSE는 동일 시간·게인에서 파형 오차/기준 에너지의 dB값으로 더 낮을수록 가깝습니다. 이들 값은 음질 점수 자체가 아닙니다.</p><h3>어택·본체·감쇠의 부호 잔차</h3><div class="wide" id="stages"></div><p class="small">기기−KM184 dB. 양쪽 원본 SNR≥10dB인 사건만 사용합니다. 어택0–40ms / 본체40–150ms / 감쇠150–300ms. 화음·아르페지오는 기존 KM184 에너지 상승 후보이며 겹친 음이 포함될 수 있습니다.</p><h3>실제 FIR 크기 응답 · 위상</h3><svg id="response" viewBox="0 0 900 250"></svg><svg id="phase" viewBox="0 0 900 230"></svg><p id="settings" class="small"></p><h3>정렬·채널 진단</h3><p id="alignment"></p><p id="qc" class="small"></p></section></div><section class="panel" style="margin-top:20px"><h2>설계에서 제외한 5타격 평균</h2><div class="wide"><table><tr><th>기기·방식</th><th>時間·대역 MAE(dB)</th><th>파형 NMSE(dB)</th></tr>'''+summary+'''</table></div><p>고정 시간 이동을 적용한 뒤에도 타격별 국소 시차가 흔들리면 위상 보정의 안정성이 제한됩니다. 낮은 코히어런스가 기기 처리·소음·방사 방향·위치 차이 중 어느 원인인지는 이 결과만으로 특정하지 않습니다. 화음과 아르페지오는 퍼커션 필터의 교차 적용 사례이며 전체 주법 검증을 뜻하지 않습니다.</p><details><summary>고정한 설계 조건과 해석</summary><p>원본 paired clock map → 설계8타격에서 선택한 채널과 단일 파형 시차 → 200–600Hz train 기준게인 → 4,097탭 필터. 각 타격400ms Tukey창, 각 사건 입력RMS로 양쪽 동일 정규화,32768점 FFT 평균 교차스펙트럼. 분모는1.05×입력스펙트럼+quiet floor. coherence0.2–0.8에서 위상을identity쪽 수축,원본jointSNR10–25dB에서신뢰도수축.150–300Hz/12–14kHz테이퍼,추가목표±12dB. 크기전용 후보는 복소IR 창 절단 후 실제 절댓값을 재합성한 대조군입니다. 같은4097tap 절단의 잔여 응답차이는 위에 표시합니다. 이전 점수와 달리 이번 비교는 공통 train 게인·고정 정렬·400ms 관측창을 사용하므로 절댓값을 앞선 점수와 이어붙이지 않습니다. 강도·차수·임계값은 평가결과로 재조정하지 않았습니다. 42.67ms 중앙지연을 오프라인 보상하며 음원 앞뒤0.5초 실제문맥을 포함합니다. 위상표시는 그 중앙지연을 제거한 응답입니다. 보정 후 유사도가 낮다고 즉시 비선형 왜곡이나 뉴럴 필요성을 단정하지 않습니다.</p></details></section><script>const data='''+json.dumps(r,ensure_ascii=False,separators=(',',':'))+''';const el=id=>document.getElementById(id),fmt=v=>v==null?'미관측':v.toFixed(2),names={percussion:'퍼커션',complex:'복합 화음',arpeggio:'아르페지오'},labels={km184:'KM184 기준',raw:'기기 원본',baseline:'기존 공통 EQ',magnitude:'원본 직접 · 크기만',complex:'원본 직접 · 크기+위상',previous:'이전 퍼커션 FIR 1,025탭'};let device='iphone',group='percussion',variant='complex',rawMode=false,position=0,audio=null,players={};const choice=()=>data.clips.find(c=>c.device===device&&c.group===group);
'''+oldjs+'''
function draw(id,m,field){let curves=['magnitude','complex'],vals=curves.flatMap(k=>m.responses[k][field]),lo=field==='magnitude_db'?-18:Math.min(-1,...vals),hi=field==='magnitude_db'?14:Math.max(1,...vals),height=field==='magnitude_db'?250:230;el(id).innerHTML='<text x="55" y="20">'+(field==='magnitude_db'?'실제 추가응답 dB':'중앙 FIR 지연을 제거한 위상 rad')+'</text>'+[lo,0,hi].map(v=>'<line x1="55" x2="870" y1="'+(40+(hi-v)/(hi-lo)*(height-95))+'" y2="'+(40+(hi-v)/(hi-lo)*(height-95))+'" stroke="#ddd"/><text x="5" y="'+(40+(hi-v)/(hi-lo)*(height-95))+'">'+v.toFixed(1)+'</text>').join('')+curves.map((k,i)=>'<polyline fill="none" stroke="'+['#c17d2b','#047d83'][i]+'" stroke-width="2" points="'+m.response_hz.map((f,j)=>(55+815*Math.log(f/80)/Math.log(18000/80))+','+(40+(hi-m.responses[k][field][j])/(hi-lo)*(height-95))).join(' ')+'"/><text x="'+(70+i*350)+'" y="'+(height-5)+'" fill="'+['#c17d2b','#047d83'][i]+'">'+labels[k]+'</text>').join('')+'<text x="55" y="'+(height-26)+'">80Hz</text><text x="820" y="'+(height-26)+'">18kHz</text>'}
function render(){stop();let c=choice();buttons('groups',Object.keys(names),group,k=>{group=k;position=0;render()},names);buttons('devices',['iphone','s21'],device,k=>{device=k;position=0;render()},{});buttons('variants',['previous','magnitude','complex'],variant,k=>{let running=!!audio;variant=k;render();if(running)play('candidate')},labels);el('selection').textContent=device.toUpperCase()+' · '+c.label+' · '+c.start_s+'–'+(c.start_s+5)+'초';el('description').textContent=variant==='previous'?'이전 첫8타격 기반 1,025탭 퍼커션 FIR입니다. 같은 고정 정렬·게인으로 다시 평가합니다.':variant==='complex'?'정규화 교차응답의 위상을 반영한 직접 FIR입니다. 타격별로 정답에 맞춰 움직이지 않습니다.':'실현된 복소 FIR 크기를 재합성한 위상0 대조군입니다. 중앙 FIR 지연은 청취에서 보상했습니다.';el('rawtoggle').textContent=rawMode?'가운데: 기존 EQ 보기':'가운데: 원본 보기';el('cards').innerHTML='';let keys={reference:'km184',baseline:rawMode?'raw':'baseline',candidate:variant};for(let [slot,key] of Object.entries(keys)){let card=document.createElement('div');card.className='card';card.dataset.slot=slot;card.innerHTML='<b>'+labels[key]+'</b><div class="spec"><img src="'+c.media[key].spectrogram+'" alt="'+labels[key]+' 스펙트로그램"><span class="cursor"></span>'+[12000,8000,2400,1200,600,80].map(f=>'<span class="freq" style="top:'+Math.min(94,100*Math.log(12000/f)/Math.log(150))+'%">'+f+'Hz</span>').join('')+'</div><div class="axis"><span>0초</span><span>5초</span></div><button>'+labels[key]+' 듣기/전환</button>'+(c.media[key].residual?'<div class="spec"><img src="'+c.media[key].residual+'" alt="'+labels[key]+' 잔차"><span class="cursor"></span></div>':'');card.querySelector('button').onclick=()=>play(slot);card.querySelectorAll('.spec').forEach(s=>s.onclick=e=>{stop();position=Math.max(0,Math.min(4.99,(e.clientX-s.getBoundingClientRect().left)/s.clientWidth*5));play(slot)});el('cards').append(card);players[slot]=new Audio(c.media[key].audio)}el('metrics').innerHTML=table(['방식','시간·대역 MAE','파형 NMSE','20ms SC','85ms SC'],Object.entries(c.scores).map(([k,v])=>[labels[k],fmt(v.frame_mae_db),fmt(v.waveform_nmse_db),fmt(v.spectral_convergence['960']),fmt(v.spectral_convergence['4096'])]));let sr=[];for(let band of [[600,1200],[1200,2400],[2400,4800],[4800,8000],[8000,12000]])for(let st of ['attack','body','decay']){let rr=c.stages.filter(v=>v.stage===st&&v.band_hz.join()===band.join());sr.push([band.join('–')+'Hz '+st+' ('+rr.length+')',...['raw','baseline','previous','magnitude','complex'].map(k=>rr.length?fmt(rr.reduce((sum,v)=>sum+v.signed_db[k],0)/rr.length):'미관측')])}el('stages').innerHTML=table(['대역·단계','원본','기존 EQ','이전 FIR','직접크기','직접복소'],sr);let m=data.models[device],q=data.channel_alignment[device];draw('response',m,'magnitude_db');draw('phase',m,'phase_rad');el('settings').textContent='크기/복소 실제 응답의80Hz–18kHz RMS차이 '+fmt(m.realized_response_difference_rms_db)+'dB. 고정게인 '+fmt(m.anchor_db)+'dB. 기존 EQ/FIR train 출력trim '+JSON.stringify(m.comparison_train_trim_db)+'dB. 길이4097탭,오프라인 지연보상42.67ms.';el('alignment').textContent='선택채널 '+q.selected_channel+' / 설계 고정 시차 '+fmt(q.fixed_offset_ms)+'ms. 설계8타격의 시차: '+q.train_offset_ms.map(fmt).join(', ')+'ms. 최대상관 시차는 실제 도달시간과 동일하다고 보장되지 않습니다. 평균 모노 감쇠 '+fmt(q.mono_attenuation_db)+'dB. 채널별 최대상관 중앙값: '+Object.entries(q.channel_median_abs_correlation).map(([k,v])=>k+'='+v.toFixed(3)).join(', ');el('qc').textContent='공통 안전배율 '+c.safety_scale.toFixed(4)+' · 4배 오버샘플링 최대피크 '+fmt(c.true_peak_dbfs)+'dBFS. 설계타격 ID: '+data.hit_results.filter(h=>h.device===device&&h.split==='design').map(h=>h.id).join(', ');sync()}
el('stop').onclick=stop;el('rewind').onclick=()=>{stop();position=0;sync()};el('rawtoggle').onclick=()=>{let running=!!audio;rawMode=!rawMode;render();if(running)play('baseline')};el('seek').oninput=e=>{let p=Number(e.target.value);stop();position=p;sync()};render();</script></main></html>'''
html=html.replace('時間·대역','시간·대역');(O/'complex-linear-percussion.html').write_text(html)
for name in ('transient-stage-filter.html','percussion-device-diagnosis.html'):
 p=O/name;s=p.read_text();link='<a href="complex-linear-percussion.html">원본 직접 크기·위상 비교</a>'
